def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        def _wrapper(*args, **kwargs):
            now = timer()
            for key, (value, timestamp) in list(cache.items()):
                if now - timestamp > ttl:
                    del cache[key]
            try:
                return cache[args]
            except KeyError:
                value = func(*args, **kwargs)
                cache[args] = (value, now)
                return value
        return _wrapper
    return wrapper

