            default observer schema
    """
    # Get the list of resources in the application manifest
    resources = app.spec.manifest.resources

    # Iterate over the resources and generate a default observer schema for each one
    for resource in resources:
        # Get the resource type and name
        resource_type = resource.type
        resource_name = resource.name

        # Generate the default observer schema for this resource
        observer_schema = {
