def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if the fixity block has a 'fixities' key
    if 'fixities' not in fixity:
        raise ValueError("Fixity block must have a 'fixities' key")

    # Check if the 'fixities' key is a list
    if not isinstance(fixity['fixities'], list):
        raise ValueError("'fixities' key must be a list")

    # Check if the 'fixities' list is empty
    if not fixity['fixities']:
        raise ValueError("'fixities' list must not be empty")

    # Check if all the items in the 'fixities' list are dictionaries
    for item in fixity['fixities']:
        if not isinstance(item, dict):
            raise ValueError("All items in 'fixities' list must be dictionaries")

    # Check if all the dictionaries in the 'fixities' list have a 'filepath' key
    for item in fixity['fixities']:
        if 'filepath' not in item:
            raise ValueError("All dictionaries in 'fixities' list must have a 'filepath' key")

    # Check if all the filepaths in the 'fixities' list are listed in the manifest
    for item in fixity['fixities']:
        if item['filepath'] not in manifest_files:
            raise ValueError(f"Filepath '{item['filepath']}' is not listed in the manifest")

    # Check if all the filepaths in the manifest are listed in the 'fixities' list
    for filepath in manifest_files:
        if filepath not in [item['filepath'] for item in fixity['fixities']]:
            raise ValueError(f"Filepath '{filepath}' is not listed in the 'fixities' list")

    # Check if all the dictionaries in the 'fixities' list have a 'fixity' key
    for item in fixity['fixities']:
        if 'fixity' not in item:
            raise ValueError("All dictionaries in 'fixities' list must have a 'fixity' key")

    # Check if all the 'fixity' values are strings
    for item in fixity['fixities']:
        if not isinstance(item['fixity'], str):
            raise ValueError("All 'fixity' values must be strings")

    # Check if all the 'fixity' values are valid
    for item in fixity['fixities']:
        if item['fixity'] not in ['md5', 'sha1', 'sha256', 'sha512']:
            raise ValueError(f"Invalid fixity value '{item['fixity']}'")

    # Check if all the dictionaries in the 'fixities' list have a 'timestamp' key
    for item in fixity['fixities']:
        if 'timestamp' not in item:
            raise ValueError("All dictionaries in 'fixities' list must have a 'timestamp' key")

    # Check if all the 'timestamp' values are integers
    for item in fixity['fixities']:
        if not isinstance(item['timestamp'], int):
            raise ValueError("All 'timestamp' values must be integers")

    # Check if all the 'timestamp' values are positive
    for item in fixity['fixities']:
        if item['timestamp'] < 0:
            raise ValueError("All 'timestamp' values must be positive")

